INSERT INTO `ai_responses_cache` VALUES ('0cb32281ef7861edcbe5bb7af830f807fb253a5b5530381831ed9ff02410f82c','Hãy phân tích tin nhắn sau đây có chứa ngôn từ thô tục, xúc phạm, thù ghét hoặc không phù hợp với môi trường thư viện trường học không? \r\n        Chỉ trả về duy nhất từ \'SAFE\' nếu an toàn, hoặc \'UNSAFE\' nếu vi phạm. Tuyệt đối không giải thích gì thêm.\r\n        Tin nhắn: \"đánh bom khủng bố bạo lực tự sát\"','UNSAFE','2026-06-04 17:25:06'),('3c42f570bd9cea1e2325fac189b07018950dbcb4589c481267bf9900ea3708c0','Hãy phân tích tin nhắn sau đây có chứa ngôn từ thô tục, xúc phạm, thù ghét hoặc không phù hợp với môi trường thư viện trường học không? \r\n        Chỉ trả về duy nhất từ \'SAFE\' nếu an toàn, hoặc \'UNSAFE\' nếu vi phạm. Tuyệt đối không giải thích gì thêm.\r\n        Tin nhắn: \"cức\"','UNSAFE','2026-06-04 17:24:41'),('3f27448d3ee136d2276a872f99ae8eb3a45af694762c32d77c5f2e2b946a5037','Hãy phân tích tin nhắn sau đây có chứa ngôn từ thô tục, xúc phạm, thù ghét hoặc không phù hợp với môi trường thư viện trường học không? \nOnly return \'SAFE\' or \'UNSAFE\'.\nMessage: \"đánh bom khủng bố bạo lực tự sát\"','UNSAFE','2026-06-04 17:25:03'),('45f5e9a1bc0ecc20fd0c6640d496c065458bf181af5f0b7396ac8093f410ea67','dế mèn phiêu lưu kí bao nhiêu ấn bản','Xin chào bạn! Hiện tại Thư viện HDPE chưa có cuốn \"Dế Mèn Phiêu Lưu Ký\" trong danh mục, nên thư viện chưa có thông tin về số lượng ấn bản của sách này. \n\nBạn có thể tìm kiếm các tác phẩm khác thuộc thể loại **Thiếu nhi** hoặc các thể loại sẵn có tại thư viện như *Văn học nước ngoài, Khoa học, Tâm lý / Sức khỏe, Kinh tế / Kinh doanh...* nhé!','2026-06-04 17:26:28'),('a6e1abc33ebd8ac3b6a2d352946ca72efbb70cb67f31fed22d351cad99a1f40e','Lập trình C++ từ cơ bản đến nâng cao còn bao nhiêu cuốn','Xin chào! Thư viện HDPE hiện đang có sẵn tổng cộng **58 cuốn** sách *\"Lập trình C++ từ cơ bản đến nâng cao\"* của tác giả Phạm Hữu Anh (Thể loại: Công nghệ thông tin) ở trạng thái **Sẵn sàng** phục vụ bạn. \n\nSố lượng chi tiết theo từng ấn bản như sau:\n* **Ấn bản 10:** 3 cuốn\n* **Ấn bản 9:** 5 cuốn\n* **Ấn bản 8:** 2 cuốn\n* **Ấn bản 7:** 4 cuốn\n* **Ấn bản 6:** 3 cuốn\n* **Ấn bản 5:** 31 cuốn\n* **Ấn bản 4:** 3 cuốn\n* **Ấn bản 3:** 2 cuốn\n* **Ấn bản 2:** 2 cuốn\n* **Ấn bản 1:** 3 cuốn\n\nBạn muốn đăng ký mượn ấn bản nào ạ?','2026-06-04 17:29:04'),('a85e2a3f13e7fc5ae1cba61eaa7dda29056b7255ae65db849adb9f2949657db0','Lập trình C++ từ cơ bản đến nâng cao còn bao nhiêu cuốn','Chào bạn, hiện tại Thư viện HDPE chưa có cuốn \"Lập trình C++ từ cơ bản đến nâng cao\" trong danh mục. \n\nBạn có thể tham khảo các đầu sách khác thuộc thể loại **Công nghệ thông tin** (như cuốn *Machine Learning Cơ bản* đang có sẵn) hoặc tìm kiếm theo các thể loại khác tại thư viện nhé!','2026-06-04 17:26:59'),('aa8c5597aecc8af9dc42b6ec306a80ee8abfe0c448c592587fb195e91140e87c','Hãy phân tích tin nhắn sau đây có chứa ngôn từ thô tục, xúc phạm, thù ghét hoặc không phù hợp với môi trường thư viện trường học không? \r\n        Chỉ trả về duy nhất từ \'SAFE\' nếu an toàn, hoặc \'UNSAFE\' nếu vi phạm. Tuyệt đối không giải thích gì thêm.\r\n        Tin nhắn: \"Hôm nay thư viện mở cửa mấy giờ ạ?\"','SAFE','2026-06-04 07:16:13'),('bc0e458d61bedeb43fd549b67624e5c2804e01068fa7e2a3a0d16e604f72257c','Hãy phân tích tin nhắn sau đây có chứa ngôn từ thô tục, xúc phạm, thù ghét hoặc không phù hợp với môi trường thư viện trường học không? \r\n        Chỉ trả về duy nhất từ \'SAFE\' nếu an toàn, hoặc \'UNSAFE\' nếu vi phạm. Tuyệt đối không giải thích gì thêm.\r\n        Tin nhắn: \"dế mèn phiêu lưu kí\"','SAFE','2026-06-04 17:24:53'),('c03a8ab4c3c84ffd15eefafce523382682d26e489dfc1cd5ca753f572e648f44','Hãy phân tích tin nhắn sau đây có chứa ngôn từ thô tục, xúc phạm, thù ghét hoặc không phù hợp với môi trường thư viện trường học không? \r\n        Chỉ trả về duy nhất từ \'SAFE\' nếu an toàn, hoặc \'UNSAFE\' nếu vi phạm. Tuyệt đối không giải thích gì thêm.\r\n        Tin nhắn: \"Hello HDPE library from QA Test!\"','SAFE','2026-06-04 06:54:20');
