INSERT INTO `announcements` VALUES (8,'Cuộc thi: Review sách hay - Nhận ngay quà tặng từ Thư viện HDPE','Nhằm khuyến khích phong trào đọc sách, Thư viện tổ chức cuộc thi viết cảm nhận về cuốn sách bạn yêu thích nhất. Giải thưởng là voucher mua sách và thẻ thành viên ưu tiên. Chi tiết xem tại Fanpage.',NULL,'contest','2024-05-15',NULL,1,1,'2026-05-24 23:29:52','2026-05-26 18:44:01'),(10,'Sự kiện: Workshop Kỹ năng đọc nhanh và ghi nhớ hiệu quả','Thư viện phối hợp cùng CLB Kỹ năng tổ chức buổi Workshop hướng dẫn các phương pháp đọc sách khoa học. Thời gian: 09:00 Thứ Bảy ngày 01/06. Địa điểm: Hội trường Lớn.',NULL,'event','2024-05-20',NULL,1,1,'2026-05-24 23:29:52','2026-05-26 18:43:50'),(11,'Cập nhật nội quy mượn trả sách (Mới)','Thư viện xin thông báo về việc áp dụng quy định giữ chỗ sách (Hard Reservation). Sinh viên đặt sách vui lòng đến nhận trong vòng 24h.',NULL,'general','2026-05-23',NULL,1,1,'2026-05-23 07:59:22','2026-05-25 12:59:22'),(12,'Hệ Thống Hoàn Thành','Các bạn có thể mượn sách ngay bây  giờ',NULL,'general',NULL,NULL,1,1,'2026-05-26 18:58:25','2026-05-26 18:58:25');
/*!40000 ALTER TABLE `announcements` ENABLE KEYS */;
