CREATE TABLE `book_imports` (
  `import_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `book_id` int(10) unsigned DEFAULT NULL COMMENT 'FK to books.book_id, set after sync',
  `invoice_code` varchar(50) NOT NULL COMMENT 'M?? h??a ????n (auto-generated if blank)',
  `title` varchar(255) NOT NULL COMMENT 'T??n s??ch nh???p',
  `author` varchar(150) NOT NULL DEFAULT 'Kh??c',
  `isbn` varchar(30) DEFAULT NULL,
  `category` varchar(100) NOT NULL DEFAULT 'Kh??c',
  `publisher` varchar(255) DEFAULT NULL,
  `published_year` year(4) DEFAULT NULL,
  `quantity` smallint(5) unsigned NOT NULL DEFAULT 1,
  `import_type` enum('purchase','donation','other') NOT NULL DEFAULT 'purchase',
  `invoice_url` varchar(500) DEFAULT NULL,
  `price` decimal(12,2) NOT NULL DEFAULT 0.00,
  `note` text DEFAULT NULL,
  `imported_by` int(10) unsigned NOT NULL COMMENT 'admin user_id',
  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'approved',
  `import_date` date DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`import_id`),
  KEY `fk_import_book` (`book_id`),
  KEY `fk_import_admin` (`imported_by`),
  CONSTRAINT `fk_import_admin` FOREIGN KEY (`imported_by`) REFERENCES `users` (`user_id`),
  CONSTRAINT `fk_import_book` FOREIGN KEY (`book_id`) REFERENCES `books` (`book_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1235 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
