/*!40000 ALTER TABLE `chat_logs` DISABLE KEYS */;
INSERT INTO `chat_logs` VALUES (1,1,'trong kho có bao nhiêu sách','Chào bạn! Hiện tại hệ thống thư viện HDPE đang cập nhật số lượng sách chính xác trong kho. \n\nBạn đang tìm kiếm tựa sách hoặc thể loại cụ thể nào không? Hãy chia sẻ để mình hỗ trợ kiểm tra và tìm kiếm giúp bạn nhé!','2026-05-27 00:11:26'),(2,1,'tô hoài có những tác phẩm nào','Chào bạn! Nhà văn Tô Hoài là một cây bút đại thụ của văn học Việt Nam với nhiều tác phẩm nổi tiếng. Các tác phẩm tiêu biểu nhất của ông gồm có:\n\n1. **Dế Mèn phiêu lưu ký** (Tác phẩm thiếu nhi kinh điển)\n2. **Vợ chồng A Phủ** (Truyện ngắn trong tập *Truyện Tây Bắc*)\n3. **Cát bụi chân ai** (Hồi ký)\n4. **O chuột** (Tập truyện về loài vật)\n\nBạn có thể tìm kiếm các tác phẩm này tại Thư viện HDPE ở quầy sách thuộc thể loại **Văn học trong nước**. Nếu cần tra cứu tình trạng còn/mất của sách trên kệ, bạn cứ báo cho tôi nhé!','2026-05-27 00:11:56'),(3,1,'có bao nhiêu ẩn bản dế mèn phiêu lưu kí','Lỗi kết nối AI: Read timed out after 2 seconds','2026-06-05 00:23:27'),(4,1,'alo','Lỗi kết nối AI: Read timed out after 2 seconds','2026-06-05 00:23:37'),(5,1,'dế mèn phiêu lưu kí bao nhiêu ấn bản','Xin chào bạn! Hiện tại Thư viện HDPE chưa có cuốn \"Dế Mèn Phiêu Lưu Ký\" trong danh mục, nên thư viện chưa có thông tin về số lượng ấn bản của sách này. \n\nBạn có thể tìm kiếm các tác phẩm khác thuộc thể loại **Thiếu nhi** hoặc các thể loại sẵn có tại thư viện như *Văn học nước ngoài, Khoa học, Tâm lý / Sức khỏe, Kinh tế / Kinh doanh...* nhé!','2026-06-05 00:26:28'),(6,1,'Lập trình C++ từ cơ bản đến nâng cao còn bao nhiêu cuốn','Chào bạn, hiện tại Thư viện HDPE chưa có cuốn \"Lập trình C++ từ cơ bản đến nâng cao\" trong danh mục. \n\nBạn có thể tham khảo các đầu sách khác thuộc thể loại **Công nghệ thông tin** (như cuốn *Machine Learning Cơ bản* đang có sẵn) hoặc tìm kiếm theo các thể loại khác tại thư viện nhé!','2026-06-05 00:26:59');
/*!40000 ALTER TABLE `chat_logs` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `notifications`
