INSERT INTO `support_tickets` VALUES (11,19,'card_issue','Không thể gia hạn sách online','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','closed','2026-05-08 18:38:41','2026-05-10 05:51:23'),(12,17,'card_issue','Không thể gia hạn sách online','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','in_progress','2026-04-26 18:38:41','2026-04-27 16:00:18'),(13,31,'card_issue','Không thể gia hạn sách online','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','closed','2026-05-04 18:38:41','2026-05-06 06:14:03'),(14,13,'card_issue','Không thể gia hạn sách online','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','open','2026-05-17 18:38:41','2026-05-17 18:38:41'),(15,24,'damaged_book','Sách mượn bị rách mất 2 trang','Dạ, em vừa mượn cuốn \"Giải tích 1\" lúc sáng, nhưng mang về mở ra mới thấy trang 45 và 46 đã bị xé rách từ trước. Em báo lại để lúc trả không bị phạt ạ.','closed','2026-05-23 18:38:41','2026-05-25 08:45:42'),(16,16,'other','Hỏi về việc đề xuất mua sách mới','Thư viện mình có cho phép sinh viên đề xuất mua sách chuyên ngành không ạ? Khoa em có mấy cuốn tham khảo tiếng Anh rất hay nhưng thư viện chưa có.','closed','2026-05-15 18:38:41','2026-05-17 08:28:39'),(17,35,'card_issue','Không thể gia hạn sách online','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','open','2026-05-16 18:38:41','2026-05-24 23:50:31'),(18,25,'damaged_book','Sách mượn bị rách mất 2 trang','Dạ, em vừa mượn cuốn \"Giải tích 1\" lúc sáng